import sys
from itertools import permutations


def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    grid = data[1:1 + n]
    count = 0
    for perm in permutations(range(n)):
        ok = all(grid[r][perm[r]] == '.' for r in range(n))
        for a in range(n):
            if not ok:
                break
            for b in range(a + 1, n):
                if abs(perm[a] - perm[b]) == b - a:
                    ok = False
                    break
        if ok:
            count += 1
    print(count)


main()
